insert into public.rappels_presence_discord (
  type_rappel, competition_id, date_competition, heure_programmee, statut,
  nb_messages, erreur, updated_at
)
select
  rappel.type_rappel,
  c.id,
  date '2030-01-15',
  rappel.heure_programmee,
  rappel.statut,
  rappel.nb_messages,
  rappel.erreur,
  rappel.updated_at
from public.competitions c
cross join (values
  ('sans_reponse_17h', time '17:00', 'echec', 0, 'TEST_SYNTHETIQUE', timestamptz '2030-01-15 17:01:00+00'),
  ('presence_sans_reponse', time '17:00', 'envoye', 1, null, timestamptz '2030-01-15 17:02:00+00'),
  ('presence_staff', time '19:00', 'envoye', 1, null, timestamptz '2030-01-15 19:01:00+00')
) as rappel(type_rappel, heure_programmee, statut, nb_messages, erreur, updated_at)
where c.nom = 'Fixture Competition';
